components.css:
.allocation-chips {
  display: flex;
  gap: 6px;
  flex-wrap: wrap;
  min-width: 0;
  max-width: 100%;
  padding-inline-start: 10px;
  border-inline-start: 1px solid var(--line);
}
.allocation-chip {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: 1px solid var(--line);
  border-radius: 8px;
  min-height: 36px;
  max-width: 100%;
  padding: 5px 12px;
  background: var(--paper);
  color: var(--muted);
  font-size: var(--text-support);
  font-weight: 600;
  line-height: 1.45;
  overflow-wrap: anywhere;
  cursor: pointer;
  transition: background-color 0.15s, border-color 0.15s, color 0.15s;
}
.allocation-chip:hover:not(:disabled) {
  border-color: var(--green);
  background: var(--canvas);
  color: var(--green);
}
.allocation-chip[aria-pressed="true"] {
  border-color: var(--green);
  background: var(--green-soft);
  color: var(--green-dark);
}
.allocation-chip[aria-pressed="true"]:hover:not(:disabled) {
  border-color: var(--green-dark);
  background: var(--green-soft);
  color: var(--green-dark);
}
.allocation-all {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 36px;
  max-width: 100%;
  padding: 5px 4px;
  border: 0;
  border-radius: 5px;
  background: transparent;
  color: var(--muted);
  font-size: var(--text-support);
  font-weight: 600;
  line-height: 1.45;
}
.allocation-all:hover:not(:disabled),
.allocation-all[aria-pressed="true"] {
  color: var(--green-dark);
  text-decoration: underline;
  text-underline-offset: 5px;
  text-decoration-thickness: 2px;
}
.allocation-chip,
  .allocation-all {
    min-height: 44px;
  }

.custom-quantities {
  margin-top: 16px;
  padding-top: 16px;
  border-top: 1px solid var(--line);
}
.parts-heading {
  display: block;
  color: var(--ink);
  font-size: var(--text-support);
  font-weight: 600;
}
.custom-quantities .field-hint {
  margin-top: 4px;
}
.parts-fields {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(min(100%, 104px), 1fr));
  align-items: end;
  gap: 12px;
  margin-top: 12px;
  min-width: 0;
}
.parts-fields > .field {
  min-width: 0;
  overflow-wrap: anywhere;
}
.parts-fields .number-field {
  display: flex;
  align-items: center;
  gap: 8px;
  min-height: 44px;
  padding: 0 10px;
  border: 1px solid #cad5ce;
  border-radius: 8px;
  background: var(--paper);
}
.number-field:focus-within {
  outline: 2px solid #429d75;
  outline-offset: 1px;
}
.number-field > input {
  flex: 1;
  min-width: 0;
  border: 0;
  border-radius: 0;
  background: transparent;
  padding: 8px 0;
  font-size: var(--text-body);
  font-variant-numeric: tabular-nums;
}
.number-field > input:focus {
  outline: none;
}
.number-field > .number-unit {
  flex-shrink: 0;
  color: var(--muted);
  font-size: var(--text-meta);
}

.details-fields {
  display: grid;
  grid-template-columns: minmax(0, 124px) minmax(0, 1fr);
  align-items: start;
  gap: 16px;
  padding-top: 16px;
}
.details-fields > .discount-field {
  max-width: 100%;
}
.item-tax-toggles {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px;
  min-height: 44px;
  max-width: 100%;
}
.item-tax-toggles > .allocation-chip {
  min-height: 44px;
  padding: 8px 12px;
}
.details-fields {
    grid-template-columns: 1fr;
  }
.details-fields > .discount-field {
    width: 124px;
  }
.number-field {
  display: flex;
  align-items: center;
  gap: 8px;
  min-height: 44px;
  padding: 0 10px;
  border: 1px solid #cad5ce;
  border-radius: 8px;
  background: var(--paper);
}
.number-field:focus-within {
  outline: 2px solid #429d75;
  outline-offset: 1px;
}
.number-field > input {
  flex: 1;
  min-width: 0;
  border: 0;
  border-radius: 0;
  background: transparent;
  padding: 8px 0;
  font-size: var(--text-body);
  font-variant-numeric: tabular-nums;
}
.number-field > input:focus {
  outline: none;
}
.number-field > .number-unit {
  flex-shrink: 0;
  color: var(--muted);
  font-size: var(--text-meta);
}

.extras-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 16px;
  margin-bottom: 16px;
}
.unit-field {
  display: flex;
  align-items: center;
  gap: 4px;
  min-width: 0;
  min-height: 44px;
  padding: 3px;
  border: 1px solid #cad5ce;
  border-radius: 8px;
  background: var(--paper);
}
.unit-field:focus-within {
  outline: 2px solid #429d75;
  outline-offset: 1px;
}
.unit-field input {
  flex: 1;
  min-width: 0;
  min-height: 36px;
  padding: 5px 8px;
  border: 0;
  background: transparent;
  font-variant-numeric: tabular-nums;
}
.unit-field input:focus {
  outline: none;
}
.unit-switch {
  display: flex;
  flex-shrink: 0;
  gap: 2px;
  padding: 2px;
  border-radius: 5px;
  background: var(--canvas);
}
.unit-switch > button {
  display: grid;
  place-items: center;
  min-width: 36px;
  min-height: 32px;
  padding: 3px 8px;
  border: 1px solid transparent;
  border-radius: 5px;
  background: transparent;
  color: var(--muted);
  font-size: var(--text-support);
  font-weight: 600;
  line-height: 1.45;
  transition: color 0.15s, background-color 0.15s, border-color 0.15s;
}
.unit-switch > button:hover:not(:disabled) {
  background: var(--green-soft);
  color: var(--green-dark);
}
.unit-switch > button[aria-pressed="true"] {
  border-color: var(--line);
  background: var(--paper);
  color: var(--green-dark);
}
@media (pointer: coarse) {
  .unit-switch > button {
    min-width: 44px;
    min-height: 44px;
  }
}
@media (max-width: 520px) {
  .extras-grid {
    grid-template-columns: 1fr;
  }
}

.parts-heading {
  display: block;
  color: var(--ink);
  font-size: var(--text-support);
  font-weight: 600;
}
.parts-heading-row {
  position: relative;
  display: flex;
  align-items: center;
  gap: 4px;
  min-width: 0;
}
.parts-help-trigger {
  display: inline-grid;
  place-items: center;
  flex-shrink: 0;
  min-width: 36px;
  min-height: 36px;
  padding: 8px;
  border: 0;
  border-radius: 8px;
  background: transparent;
  color: var(--muted);
}
.parts-help-trigger:hover,
.parts-help-trigger[aria-expanded="true"] {
  background: var(--green-soft);
  color: var(--green-dark);
}
.parts-tooltip {
  position: absolute;
  z-index: 20;
  top: 100%;
  inset-inline-start: 0;
  width: min(340px, 100%);
  max-height: calc(100dvh - 32px);
  overflow: auto;
  padding: 16px;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: var(--paper);
  color: var(--ink);
  box-shadow: 0 8px 24px #192d281a;
  font-size: var(--text-support);
  line-height: 1.7;
}
.parts-tooltip[data-placement="top"] {
  top: auto;
  bottom: 100%;
}
.parts-tooltip p,
.parts-tooltip ul {
  margin-top: 8px;
  color: var(--ink);
}
.parts-tooltip ul {
  margin-bottom: 0;
  padding-inline-start: 20px;
}
.parts-tooltip li + li {
  margin-top: 4px;
}
@media (pointer: coarse) {
  .parts-help-trigger {
    min-width: 44px;
    min-height: 44px;
  }
}

.pin-field {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 8px;
  min-width: 0;
}
.pin-field > span:first-child {
  color: var(--muted);
  font-size: var(--text-body);
  font-weight: 500;
}
.pin-boxes {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 8px;
  width: min(100%, 240px);
}
.pin-boxes > input {
  min-width: 0;
  min-height: 52px;
  padding: 8px 0;
  text-align: center;
  font-size: var(--text-title);
  font-weight: 600;
  font-variant-numeric: tabular-nums;
  line-height: 1.4;
  letter-spacing: normal;
  caret-color: var(--green);
}
.pin-boxes > input[aria-invalid="true"] {
  border-color: var(--danger);
}

.item-payer {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 10px 16px;
  margin-top: 14px;
  padding-top: 12px;
  border-top: 1px dashed var(--line);
}
.payer-choice {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 10px;
  flex: 1 1 260px;
  min-width: 0;
}
.payer-choice .allocation-chips {
  padding-inline-start: 0;
  border-inline-start: 0;
}
.payer-label {
  color: var(--muted);
  font-size: var(--text-support);
  font-weight: 600;
}
.payer-promptpay-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  min-height: 44px;
  margin-left: auto;
  padding: 8px 10px;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: var(--paper);
  color: var(--green);
  font-size: var(--text-meta);
  font-weight: 600;
}
.payer-promptpay-button:hover:not(:disabled) {
  border-color: var(--green);
  background: var(--green-soft);
}
.item-payer > .field-hint {
  flex-basis: 100%;
  margin: 0;
}
.promptpay-dialog {
  width: min(440px, calc(100% - 32px));
  max-height: calc(100dvh - 32px);
  margin: auto;
  padding: 0;
  border: 0;
  border-radius: 14px;
  background: var(--paper);
  color: var(--ink);
  box-shadow: 0 20px 60px rgb(25 45 40 / 22%);
  overflow: auto;
}
.promptpay-dialog::backdrop {
  background: rgb(25 45 40 / 38%);
}
.promptpay-dialog-content {
  padding: 24px;
}
.promptpay-dialog-heading {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
}
.promptpay-dialog-heading h2 {
  padding-top: 6px;
  font-size: var(--text-title);
  line-height: 1.5;
  overflow-wrap: anywhere;
}
.promptpay-dialog-heading .icon-button {
  min-width: 44px;
  min-height: 44px;
  flex-shrink: 0;
}
.promptpay-dialog-content > .field-hint {
  margin: 4px 0 20px;
  overflow-wrap: anywhere;
}
.promptpay-dialog input {
  font-variant-numeric: tabular-nums;
}
.promptpay-dialog input[aria-invalid="true"] {
  border-color: var(--danger);
}
.promptpay-dialog-actions {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1.5fr);
  gap: 10px;
  margin-top: 24px;
}
.promptpay-dialog-actions .button {
  padding-inline: 8px;
}

.net-summary {
  max-width: 320px;
  margin-top: 16px;
  padding-top: 16px;
  border-top: 1px dashed var(--line);
}
.net-summary h3 {
  font-size: var(--text-body);
  font-weight: 700;
  margin: 0 0 8px;
}
.net-people,
.net-transfers {
  list-style: none;
  padding: 0;
  margin: 0;
}
.net-person {
  padding: 9px 0;
}
.net-person + .net-person {
  border-top: 1px solid var(--line);
}
.net-person-heading {
  display: grid;
  grid-template-columns: 28px minmax(0, 1fr) minmax(0, auto);
  align-items: center;
  gap: 9px;
}
.net-person-name {
  min-width: 0;
  font-size: var(--text-body);
  font-weight: 600;
  overflow-wrap: anywhere;
}
.net-person-result {
  display: grid;
  justify-items: end;
  gap: 2px;
  min-width: 0;
  text-align: right;
}
.net-person-result > div {
  display: flex;
  justify-content: flex-end;
  align-items: baseline;
  flex-wrap: wrap;
  gap: 0 6px;
}
.net-person-result span {
  display: block;
  color: var(--muted);
  font-size: var(--text-meta);
  line-height: 1.5;
}
.net-person-result b {
  display: block;
  margin-top: 0;
  font-size: var(--text-body);
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  overflow-wrap: anywhere;
}
.net-person-credit > span,
.net-person-credit > b {
  color: var(--green);
}
.net-person-details {
  display: grid;
  grid-template-columns: auto auto;
  justify-content: space-between;
  gap: 8px;
  margin: 5px 0 0;
  font-size: var(--text-meta);
}
.net-person-details > div {
  display: flex;
  align-items: baseline;
  gap: 5px;
  min-width: 0;
  white-space: nowrap;
}
.net-person-details > div:last-child {
  text-align: right;
}
.net-person-details dt {
  color: var(--muted);
  white-space: nowrap;
}
.net-person-details dd {
  margin: 0;
  color: var(--ink);
  font-variant-numeric: tabular-nums;
  overflow-wrap: anywhere;
}
.net-transfer-section {
  margin-top: 8px;
  padding-top: 14px;
  border-top: 1px solid var(--line);
}
.net-transfers > li {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, auto);
  align-items: center;
  gap: 12px;
  padding: 8px 0;
  font-size: var(--text-support);
}
.net-transfers > li + li {
  border-top: 1px solid var(--line);
}
.net-transfer-route {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 6px;
  min-width: 0;
}
.net-transfer-route > span {
  min-width: 0;
  max-width: 100%;
  overflow-wrap: anywhere;
}
.net-transfer-arrow {
  display: inline-flex;
  color: var(--muted);
}
.net-transfers b {
  text-align: right;
  font-size: var(--text-support);
  font-variant-numeric: tabular-nums;
  overflow-wrap: anywhere;
}
.net-transfer-section > .field-hint {
  margin-top: 12px;
  font-size: var(--text-meta);
}

.brand {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  min-height: 44px;
  white-space: nowrap;
}
.brand-logo {
  display: block;
  width: 40px;
  height: 40px;
  flex-shrink: 0;
}
.brand-wordmark {
  display: flex;
  flex-direction: column;
  gap: 1px;
}
.brand-product {
  color: var(--ink);
  line-height: 1.35;
  font-size: 1.375rem;
  font-weight: 600;
  letter-spacing: -0.02em;
}
.brand-english {
  color: var(--green);
  font-size: 0.6875rem;
  line-height: 1.3;
  font-weight: 600;
  letter-spacing: 0.04em;
}

.language-options {
  padding: 4px 0;
}
.user-menu-panel > .language-options {
  border-top: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
  margin: 4px 0;
}
.language-options > p {
  padding: 4px 10px;
  font-size: var(--text-meta);
}
.language-options > button {
  display: flex;
  align-items: center;
  justify-content: space-between;
  min-height: 44px;
  width: 100%;
  padding: 8px 10px;
  border-radius: 6px;
  font-size: var(--text-support);
  font-family: inherit;
  text-align: left;
  background: transparent;
  border: 0;
  cursor: pointer;
}
.language-options > button:hover,
.language-options > button[aria-pressed="true"] {
  background: var(--green-soft);
  color: var(--green-dark);
}
.language-menu > summary {
  min-width: 44px;
  justify-content: center;
  padding: 8px;
  font-size: var(--text-meta);
  font-weight: 600;
}
